-- ── 2a. curate existing rows (59) ──────────────────────────────────────────
UPDATE exercise_muscle SET region='long_head', length_bias='lengthened', rep_low=8, rep_high=15, sfr_tier='high', rationale='The long head is biarticular and reaches its optimal length-tension only when the shoulder is flexed, so both readings of this movement (overhead extension and lying extension) load it at length -- Stasinaki recorded 15 pct vs 10 pct thickness for overhead versus pushdown, and Wakahara''s MRI put lying triceps extension''s growth in the proximal (long-head) region.', citation='schoenfeld-2021-ch8-program-design.md' WHERE exercise_name='Dumbbell Tricep Extension' AND muscle='triceps' AND citation IS NULL;
UPDATE exercise_muscle SET region='long_head', length_bias='lengthened', rep_low=8, rep_high=15, sfr_tier='high', rationale='Pressing from behind the head keeps the humerus overhead, which elongates the long head at the shoulder while it works at the elbow -- the passive-tension case the vault singles out as the deliberate way to design a long-head exercise.', citation='schoenfeld-2021-ch8-program-design.md' WHERE exercise_name='Seated Tricep Press' AND muscle='triceps' AND citation IS NULL;
UPDATE exercise_muscle SET region='lateral_head', length_bias='mid', rep_low=8, rep_high=20, sfr_tier='high', rationale='With the humerus held at the side the long head is slackened at the shoulder and the medial and lateral heads take over, making the pushdown the complement to overhead work rather than a substitute for it.', citation='schoenfeld-2021-ch8-program-design.md' WHERE exercise_name='Cable Tricep Pushdown' AND muscle='triceps' AND citation IS NULL;
UPDATE exercise_muscle SET region='lateral_head', length_bias='mid', rep_low=8, rep_high=20, sfr_tier='high', rationale='Read as a rope pushdown (the overhead rope variant is already curated separately), the humerus stays at the side and the medial and lateral heads carry the elbow extension.', citation='schoenfeld-2021-ch8-program-design.md' WHERE exercise_name='Cable Rope Tricep Extension' AND muscle='triceps' AND citation IS NULL;
UPDATE exercise_muscle SET region='medial_head', length_bias='mid', rep_low=10, rep_high=20, sfr_tier='moderate', rationale='The single-arm reverse-grip pushdown keeps the humerus pinned at the side, the position in which the vault records the medial and lateral heads as most active and the long head as slack.', citation='schoenfeld-2021-ch8-program-design.md' WHERE exercise_name='Cable One Arm Underhand Tricep Extension' AND muscle='triceps' AND citation IS NULL;
UPDATE exercise_muscle SET region='lateral_head', length_bias='shortened', rep_low=8, rep_high=15, sfr_tier='moderate', rationale='The shoulder sits extended behind the torso, which shortens the long head at the shoulder and leaves the medial and lateral heads to drive elbow extension into a fully shortened lockout.', citation='schoenfeld-2021-ch8-program-design.md' WHERE exercise_name='Bench Dip' AND muscle='triceps' AND citation IS NULL;
UPDATE exercise_muscle SET region='lateral_head', length_bias='shortened', rep_low=12, rep_high=25, sfr_tier='moderate', rationale='Band tension rises as the band lengthens, so resistance peaks at the locked-out (shortened) end rather than at the stretch, and the at-side humerus places the load on the medial and lateral heads.', citation='schoenfeld-2021-ch8-program-design.md' WHERE exercise_name='Mini Loop Band Tricep Press' AND muscle='triceps' AND citation IS NULL;
