UPDATE exercise_muscle SET region='mid_chest', length_bias='mid', rep_low=6, rep_high=15, sfr_tier='high', rationale='A flat horizontal press loads the sternal head, and the fixed machine path holds the pecs near mid-length rather than accentuating either end of the range.', citation='schoenfeld-2021-ch8-program-design.md' WHERE exercise_name='Hammerstrength Chest Press' AND muscle='chest' AND citation IS NULL;
UPDATE exercise_muscle SET region='mid_chest', length_bias='lengthened', rep_low=6, rep_high=12, sfr_tier='high', rationale='Flat pressing targets the sternal head, and dumbbells let the humeri travel below the torso line so the pecs are loaded in the stretched position the vault identifies as the most anabolic part of the range.', citation='schoenfeld-2021-ch8-program-design.md' WHERE exercise_name='Dumbbell Bench Press' AND muscle='chest' AND citation IS NULL;
UPDATE exercise_muscle SET region='mid_chest', length_bias='mid', rep_low=6, rep_high=15, sfr_tier='high', rationale='Flat machine pressing loads the sternal head with a guided path that neither accentuates the stretch nor unloads at lockout the way a barbell does.', citation='schoenfeld-2021-ch8-program-design.md' WHERE exercise_name='Machine Bench Press' AND muscle='chest' AND citation IS NULL;
UPDATE exercise_muscle SET region='mid_chest', length_bias='lengthened', rep_low=8, rep_high=15, sfr_tier='high', rationale='The chest fly is the vault''s own worked example of a long-length-accentuated exercise -- peak torque falls where the sternal head is maximally stretched.', citation='schoenfeld-2021-ch8-program-design.md' WHERE exercise_name='Dumbbell Fly' AND muscle='chest' AND citation IS NULL;
UPDATE exercise_muscle SET region='upper_chest', length_bias='lengthened', rep_low=6, rep_high=12, sfr_tier='high', rationale='A 30-45 degree incline shifts the line of pull onto the clavicular head, and the dumbbell path allows a deep bottom position that loads it at long length.', citation='schoenfeld-2021-ch8-program-design.md' WHERE exercise_name='Dumbbell Incline Bench Press' AND muscle='chest' AND citation IS NULL;
UPDATE exercise_muscle SET region='upper_chest', length_bias='lengthened', rep_low=6, rep_high=12, sfr_tier='high', rationale='A 30-45 degree incline shifts the line of pull onto the clavicular head, and the dumbbell path allows a deep bottom position that loads it at long length.', citation='schoenfeld-2021-ch8-program-design.md' WHERE exercise_name='Incline Bench Press (Dumbbell)' AND muscle='chest' AND citation IS NULL;
