INSERT INTO exercise_muscle (exercise_name, muscle, role, credit, region, length_bias, rep_low, rep_high, sfr_tier, rationale, citation) SELECT 'Push Up', 'chest', 'primary', 1.0, 'mid_chest', 'mid', 8, 20, 'moderate', 'The push-up is a horizontal push, whose primary muscles are the chest with the anterior delts, but the closed-chain bodyweight load caps how much mechanical tension it can deliver to a trained lifter.', 'helms-2018-lv4-exercise-selection.md' WHERE NOT EXISTS (SELECT 1 FROM exercise_muscle WHERE exercise_name='Push Up' AND muscle='chest');
