UPDATE exercise_muscle SET region='biceps_brachii', length_bias='shortened', rep_low=10, rep_high=20, sfr_tier='moderate', rationale='Supinated curling loads all the elbow flexors, but band tension climbs as the band lengthens so peak resistance lands at full elbow flexion rather than at the stretch.', citation='schoenfeld-2021-ch8-program-design.md' WHERE exercise_name='Handle Band Bicep Curl' AND muscle='biceps' AND citation IS NULL;
