UPDATE exercise_muscle SET region='short_head', length_bias='lengthened', rep_low=8, rep_high=15, sfr_tier='high', rationale='The preacher angle abducts and flexes the humerus, which is where the short head is maximally active and the long head is actively insufficient, and peak torque falls at the extended bottom where that short head is stretched.', citation='schoenfeld-2021-ch8-program-design.md' WHERE exercise_name='Machine Preacher Curl' AND muscle='biceps' AND citation IS NULL;
