UPDATE exercise_muscle SET region='long_head', length_bias='lengthened', rep_low=8, rep_high=15, sfr_tier='high', rationale='The incline drops the humerus behind the body, the exact position in which the vault records the long head as maximally active and stretched across both the shoulder and the elbow.', citation='schoenfeld-2021-ch8-program-design.md' WHERE exercise_name='Incline Hammer Curl' AND muscle='biceps' AND citation IS NULL;
