UPDATE exercise_muscle SET region='obliques', length_bias='mid', rep_low=10, rep_high=20, sfr_tier='moderate', rationale='The vault lists trunk rotations as the training method for the obliques and internal abdominis, which it identifies as the primary generators of the intra-abdominal pressure that protects the lumbar spine.', citation='injury-prevention-lumbar.md' WHERE exercise_name='Loop Band Standing Ab Twist' AND muscle='abs' AND citation IS NULL;
UPDATE exercise_muscle SET region='obliques', length_bias='mid', rep_low=12, rep_high=25, sfr_tier='moderate', rationale='Seated loaded rotation trains the obliques and internal abdominis, the muscles the vault credits with generating intra-abdominal pressure, though the light implement caps the tension available.', citation='injury-prevention-lumbar.md' WHERE exercise_name='Medicine Ball Russian Twist' AND muscle='abs' AND citation IS NULL;
INSERT INTO exercise_muscle (exercise_name, muscle, role, credit, region, length_bias, rep_low, rep_high, sfr_tier, rationale, citation) SELECT 'Leg Extension', 'quads', 'primary', 1.0, 'rectus_femoris', 'shortened', 8, 20, 'high', 'Open-chain knee extension maximally activates the rectus femoris -- the head that squat-only training failed to grow in Fonseca -- and the vault classifies leg extension at end range as short-length accentuated.', 'schoenfeld-2021-ch8-program-design.md' WHERE NOT EXISTS (SELECT 1 FROM exercise_muscle WHERE exercise_name='Leg Extension' AND muscle='quads');
INSERT INTO exercise_muscle (exercise_name, muscle, role, credit, region, length_bias, rep_low, rep_high, sfr_tier, rationale, citation) SELECT 'Leg Press', 'quads', 'primary', 1.0, 'vastii', 'lengthened', 6, 12, 'high', 'Multi-joint pressing maximally activates the vasti, and a deep bottom position loads them at long knee flexion angles where the vault records growth at every measured site.', 'schoenfeld-2021-ch8-program-design.md' WHERE NOT EXISTS (SELECT 1 FROM exercise_muscle WHERE exercise_name='Leg Press' AND muscle='quads');
INSERT INTO exercise_muscle (exercise_name, muscle, role, credit, region, length_bias, rep_low, rep_high, sfr_tier, rationale, citation) SELECT 'Hack Squat', 'quads', 'primary', 1.0, 'vastii', 'lengthened', 6, 12, 'high', 'The vault classes the hack squat as a lower machine compound at 6-12 reps and RPE 6-9, and the guided deep bottom loads the vasti at long muscle length without the balance demand of a free squat.', 'helms-2018-qsg-program-building.md' WHERE NOT EXISTS (SELECT 1 FROM exercise_muscle WHERE exercise_name='Hack Squat' AND muscle='quads');
UPDATE exercise_muscle SET region='vastii', length_bias='lengthened', rep_low=6, rep_high=12, sfr_tier='moderate', rationale='Fonseca found the Smith squat alone failed to significantly develop the vastus medialis and rectus femoris, so it is a vasti loader that must be paired with knee extension rather than a complete quad exercise.', citation='exercise-selection-hypertrophy.md' WHERE exercise_name='Smith Machine Squat' AND muscle='quads' AND citation IS NULL;
UPDATE exercise_muscle SET region='vastii', length_bias='lengthened', rep_low=8, rep_high=15, sfr_tier='moderate', rationale='A wide-stance squat is a multi-joint knee-extension pattern loading the vasti through a deep bottom, and the vault records stances at or beyond 140 pct shoulder width as increasing glute max contribution alongside it.', citation='schoenfeld-2021-ch8-program-design.md' WHERE exercise_name='Kettlebell Sumo Squat' AND muscle='quads' AND citation IS NULL;
UPDATE exercise_muscle SET region='vastii', length_bias='lengthened', rep_low=8, rep_high=15, sfr_tier='moderate', rationale='A wide-stance squat is a multi-joint knee-extension pattern loading the vasti through a deep bottom, and the vault records stances at or beyond 140 pct shoulder width as increasing glute max contribution alongside it.', citation='schoenfeld-2021-ch8-program-design.md' WHERE exercise_name='Sumo Squat (Kettlebell)' AND muscle='quads' AND citation IS NULL;
UPDATE exercise_muscle SET region='vastii', length_bias='lengthened', rep_low=15, rep_high=30, sfr_tier='low', rationale='The squat pattern loads the vasti at long knee flexion angles, but bodyweight alone sits at or below the roughly 30 pct 1RM minimum effective loading threshold for a trained lifter, so this functions as preparatory volume rather than a growth stimulus.', citation='load-selection-hypertrophy.md' WHERE exercise_name='Air Squats' AND muscle='quads' AND citation IS NULL;
UPDATE exercise_muscle SET region='vastii', length_bias='lengthened', rep_low=15, rep_high=30, sfr_tier='low', rationale='The squat pattern loads the vasti at long knee flexion angles, but bodyweight alone sits at or below the roughly 30 pct 1RM minimum effective loading threshold for a trained lifter, so this functions as preparatory volume rather than a growth stimulus.', citation='load-selection-hypertrophy.md' WHERE exercise_name='Squat (Bodyweight)' AND muscle='quads' AND citation IS NULL;
UPDATE exercise_muscle SET region='vastii', length_bias='shortened', rep_low=15, rep_high=30, sfr_tier='low', rationale='Band resistance peaks at the top of the squat where the band is most stretched and the vasti are shortened, and the achievable band load falls short of the roughly 30 pct 1RM effective threshold.', citation='load-selection-hypertrophy.md' WHERE exercise_name='Handle Band Squat' AND muscle='quads' AND citation IS NULL;
