UPDATE exercise_muscle SET region='knee_flexion', length_bias='shortened', rep_low=8, rep_high=20, sfr_tier='high', rationale='Knee flexion exercises preferentially target the biceps femoris and are required because multi-joint lower-body work produces only about half the hamstring EMG of single-joint work; the prone position leaves the hip extended, so the vault notes the RDL loads the hamstring at stretch better than the lying curl does.', citation='schoenfeld-2021-ch8-program-design.md' WHERE exercise_name='Lying Hamstrings Curl' AND muscle='hamstrings' AND citation IS NULL;
UPDATE exercise_muscle SET region='knee_flexion', length_bias='shortened', rep_low=8, rep_high=20, sfr_tier='high', rationale='Knee flexion exercises preferentially target the biceps femoris and are required because multi-joint lower-body work produces only about half the hamstring EMG of single-joint work; the prone position leaves the hip extended, so the vault notes the RDL loads the hamstring at stretch better than the lying curl does.', citation='schoenfeld-2021-ch8-program-design.md' WHERE exercise_name='Lying Leg Curl (Machine)' AND muscle='hamstrings' AND citation IS NULL;
UPDATE exercise_muscle SET region='knee_flexion', length_bias='shortened', rep_low=8, rep_high=20, sfr_tier='moderate', rationale='Unilateral standing knee flexion trains the biceps femoris through the vault''s required knee-flexion category, but the extended hip leaves the hamstring short at its proximal joint throughout the movement.', citation='schoenfeld-2021-ch8-program-design.md' WHERE exercise_name='Standing Leg Curl' AND muscle='hamstrings' AND citation IS NULL;
UPDATE exercise_muscle SET region='gluteus_maximus', length_bias='shortened', rep_low=8, rep_high=15, sfr_tier='high', rationale='The hip thrust produces the greatest gluteus maximus EMG of the tested exercises with peak torque at the end of hip extension, which is the short-length half of the coverage the vault says the glute max requires.', citation='schoenfeld-2021-ch8-program-design.md' WHERE exercise_name='Barbell Hip Thrust' AND muscle='glutes' AND citation IS NULL;
UPDATE exercise_muscle SET region='gluteus_maximus', length_bias='shortened', rep_low=12, rep_high=25, sfr_tier='moderate', rationale='The thrust pattern puts peak glute max torque at the end of hip extension, and band tension rising with elongation reinforces that shortened-position loading while capping absolute load.', citation='schoenfeld-2021-ch8-program-design.md' WHERE exercise_name='Mini Loop Band Glute Thrust' AND muscle='glutes' AND citation IS NULL;
UPDATE exercise_muscle SET region='gluteus_maximus', length_bias='shortened', rep_low=10, rep_high=20, sfr_tier='moderate', rationale='The vault lists kettlebell swings among ballistic stretch-shortening-cycle exercises trained for the eccentric-to-concentric transition, so the elastic recoil and the hip-extension lockout, not sustained tension at length, are what the movement delivers.', citation='stretch-shortening-cycle.md' WHERE exercise_name='Kettlebell Swing' AND muscle='glutes' AND citation IS NULL;

